SELECT sku, JSON_VALUE(attrs, '$.layout') AS layout, JSON_EXISTS(attrs, '$.wireless') AS has_wireless, JSON_QUERY(attrs, '$.tags') AS tags
FROM products WHERE attrs IS NOT NULL ORDER BY sku;

